config = contract.lwf_state_id
if not config:
    result = 0.0
else:
    month = payslip.date_to.month
    if config.periodicity == 'monthly':
        is_charge_month = True
    elif config.periodicity == 'annual':
        is_charge_month = bool(config.charge_month_h1) and int(config.charge_month_h1) == month
    else:  # half_yearly
        if month in (4, 5, 6, 7, 8, 9):
            is_charge_month = bool(config.charge_month_h1) and int(config.charge_month_h1) == month
        else:
            is_charge_month = bool(config.charge_month_h2) and int(config.charge_month_h2) == month
    if not is_charge_month:
        result = 0.0
    else:
        wage = categories.GROSS
        slabs = config.slab_line_ids.filtered(lambda l: l.lower_bound <= wage and (not l.upper_bound or wage <= l.upper_bound))
        result = slabs[0].employee_amount if slabs else 0.0

